ALTER TABLE public.members ADD COLUMN IF NOT EXISTS manager_set_at timestamptz;
CREATE OR REPLACE FUNCTION public.manager_set_status(p_member uuid, p_status presence_status) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$ BEGIN IF NOT public.is_manager() THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; UPDATE public.members SET status=p_status, manager_set_at=now() WHERE id=p_member; IF NOT FOUND THEN RAISE EXCEPTION 'Member not found'; END IF; END; $$;
CREATE OR REPLACE FUNCTION public.list_member_presence() RETURNS SETOF members LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT m.id,m.display_name,CASE WHEN c.active OR (m.manager_set_at IS NOT NULL AND m.manager_set_at >= coalesce(c.ended,'-infinity'::timestamptz)) THEN m.status ELSE 'offline'::public.presence_status END,CASE WHEN c.active OR m.status='offline' OR (m.manager_set_at IS NOT NULL AND m.manager_set_at >= coalesce(c.ended,'-infinity'::timestamptz)) THEN m.status_updated_at ELSE coalesce(c.ended,m.status_updated_at) END,m.created_at,m.manager_set_at FROM public.members m LEFT JOIN LATERAL(SELECT bool_or(closed_at IS NULL AND last_seen_at>now()-interval '3 minutes') AS active,max(coalesce(closed_at,last_seen_at+interval '3 minutes')) AS ended FROM public.member_connections WHERE member_id=m.id)c ON true; $$;